"""Conversation names generated by a dedicated LLM (role "title") from the user's first question."""

from __future__ import annotations

import logging
import uuid
from datetime import datetime, timezone

from langchain_core.messages import HumanMessage, SystemMessage
from orchestrator.llms import Timer, call_record, get_llm

from app.db.models import Conversation, LlmCall

log = logging.getLogger(__name__)

TITLE_PROMPT = ("You name chat conversations about ISRO and the Indian space programme. Return only a short, "
                "specific title of 3 to 7 words for a conversation that starts with the user's message. "
                "No quotes, no trailing punctuation.")


def clean_title(text: str) -> str:
    title = " ".join(text.strip().strip('"\'').split())
    return title.rstrip(".!?:;")[:200] or "New conversation"


async def generate_title(question: str) -> tuple[str, dict]:
    """Return (title, llm_call record)."""
    with Timer() as t:
        msg = await get_llm("title").ainvoke([SystemMessage(TITLE_PROMPT), HumanMessage(question[:1000])])
    text = msg.content if isinstance(msg.content, str) else str(msg.content)
    return clean_title(text), call_record("title", msg, t.seconds)


async def title_conversation(*, sessionmaker, hub, user_id: uuid.UUID, conversation_id: uuid.UUID,
                             thread_id: uuid.UUID, question: str) -> None:
    """Generate and store a title if the conversation has none; notify the user's sockets."""
    try:
        title, rec = await generate_title(question)
        async with sessionmaker() as session:
            conv = await session.get(Conversation, conversation_id)
            if conv is None or conv.title:          # titled meanwhile (e.g. renamed by the user)
                return
            conv.title, conv.title_source = title, "generated"
            session.add(LlmCall(run_id=None, thread_id=thread_id, conversation_id=conversation_id, user_id=user_id,
                                node="title", **{k: rec[k] for k in rec if k in LLM_CALL_FIELDS}))
            await session.commit()
        await hub.publish_user(str(user_id), {"type": "conversation_titled", "conversation_id": str(conversation_id),
                                              "title": title, "ts": datetime.now(timezone.utc).isoformat()})
    except Exception:  # noqa: BLE001 - a missing title must never break a run
        log.exception("title generation failed for conversation %s", conversation_id)


LLM_CALL_FIELDS = {"role", "model", "input_tokens", "output_tokens", "reasoning_tokens", "cached_tokens", "seconds",
                   "ratelimit_remaining_requests", "ratelimit_remaining_tokens"}
